        r'singularity', r'accretion', r'gravitational\s+wave', r'no\-?hair', r'\bads/cft\b|ads\s*/\s*cft',
        r'quasinormal', r'\bspin\b\s+parameter', r'general\s+relativity'
    ],
    'DNA': [
        r'\bdna\b', r'double\s+helix', r'base\s+pair', r'nucleotid', r'genom', r'chromosom',
        r'sequenc', r'polymerase', r'\brna\b', r'crisp?r', r'gene\b', r'genes\b', r'protein'
    ],
    'music_history': [
        r'\bmusic\b', r'music\s+history', r'symphon', r'opera', r'composer', r'baroque',
        r'romantic\s+period', r'classical\s+period', r'renaissance\s+music',
        r'jazz', r'blues', r'hip\-?hop', r'rock\b', r'folk\b', r'sonata', r'concerto'
    ],
}

for p in FOLDERS.values():
    p.mkdir(exist_ok=True)

TAG_RE = re.compile(r'<[^>]+>')
WS_RE = re.compile(r'\s+')


def extract_text_pdf(path: Path) -> str:
    try:
        r = subprocess.run(
            ['pdftotext', '-f', '1', '-l', '2', '-nopgbrk', '-q', str(path), '-'],
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            check=False,
        )
        txt = r.stdout.decode('utf-8', errors='ignore')
        if len(txt.strip()) >= 80:
            return txt
    except Exception:
        pass

    try:
        from pdfminer.high_level import extract_text  # type: ignore

        return extract_text(str(path), page_numbers=[0, 1]) or ''
    except Exception:
        return ''


def extract_text_docx(path: Path) -> str:
    try:
        with zipfile.ZipFile(path) as z:
            xml = z.read('word/document.xml').decode('utf-8', errors='ignore')
        xml = html.unescape(xml)
        txt = TAG_RE.sub(' ', xml)
        return WS_RE.sub(' ', txt)
    except Exception:
        return ''


def extract_text_pptx(path: Path) -> str:
    try:
        with zipfile.ZipFile(path) as z:
            parts = []
            for name in sorted(z.namelist()):
                if name.startswith('ppt/slides/slide') and name.endswith('.xml'):
                    parts.append(z.read(name).decode('utf-8', errors='ignore'))
                elif name.startswith('ppt/notesSlides/notesSlide') and name.endswith('.xml'):
                    parts.append(z.read(name).decode('utf-8', errors='ignore'))
        xml = html.unescape('\n'.join(parts))
        txt = TAG_RE.sub(' ', xml)
        return WS_RE.sub(' ', txt)
    except Exception:
        return ''


def extract_text(path: Path) -> str:
