    t = text.lower()
    s = 0
    for pat in KW[cat]:
        s += len(re.findall(pat, t))
    return s


files = sorted([p for p in ROOT.iterdir() if p.is_file()])
if not files:
    raise SystemExit('No files found to organize.')

plan: dict[Path, str] = {}
reasons: dict[Path, str] = {}

for f in files:
    txt = extract_text(f)
    scores = {c: score(txt, c) for c in PRIMARY}
    best_cat = max(PRIMARY, key=lambda c: (scores[c], -PRIMARY.index(c)))
